//! QLocale: locale names, date/time names and formats and the QML Locale type's other data
//! (numbers: `locale_num`) from Qt 6.12's CLDR tables (`locale_data.rs`, generated by
//! tools/gen/locale/gen.py), and the system locale QSystemLocale builds from the environment.

use crate::locale_data::{
    LANGUAGES, NAMES, RECORD_LEN, RECORDS, ROOT_ZONE_NAMES, SCRIPT_ZONE_NAMES, SCRIPTS, ZONE_NAMES,
    ZONES,
};

/// QLocale::FormatType.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Fmt {
    Long = 0,
    Short = 1,
    Narrow = 2,
}

impl Fmt {
    /// QML `Locale.LongFormat` (0) / `ShortFormat` (1) / `NarrowFormat` (2).
    pub fn from_num(n: f64) -> Fmt {
        match n as i64 {
            1 => Fmt::Short,
            2 => Fmt::Narrow,
            _ => Fmt::Long,
        }
    }
}

/// One QLocale: an index into `RECORDS`, or [`Locale::SYSTEM`].
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Locale(pub u16);

const AM: usize = 114;
const FORMATS: usize = 116;
/// Index of the first number field of a record (see tools/gen/locale/gen.py).
pub(crate) const NUM: usize = 122;
const ZONE: usize = 136;
const NAME: usize = 138;
const NATIVE_LANGUAGE: usize = 142;
const PERCENT: usize = 144;
const MEASUREMENT: usize = 146;
const FIRST_DAY: usize = 147;
const UI_LANGUAGES: usize = 149;
const CURRENCY_NAME: usize = 150;
const LIST: usize = 151;
const UNITS: usize = 155;
/// "1" where ICU has no data for the locale's name.
const NO_ICU_DATA: usize = 156;

thread_local! {
    static SPLIT: std::cell::RefCell<Vec<Option<&'static [&'static str]>>> =
        std::cell::RefCell::new(vec![None; RECORDS.len()]);
    /// The system locale's fields per environment it was read in.
    static SYSTEM: std::cell::RefCell<Vec<(SystemEnv, &'static [&'static str])>> =
        const { std::cell::RefCell::new(Vec::new()) };
}

/// Whether `territory` is the likely-subtags territory of `lang` (`de`, `DE`): the one
/// QLocale gives the bare language.
pub(crate) fn is_likely_territory(lang: &str, territory: &str) -> bool {
    index_of(lang).is_some_and(|l| index_of(&format!("{lang}_{territory}")) == Some(l))
}

/// The name of `zone` in the row `names` of ZONE_NAMES; None where Qt has no name.
fn zone_name_in(names: usize, zone: &str, daylight: bool, long: bool) -> Option<&'static str> {
    let group = ZONES.binary_search_by(|(id, _)| (*id).cmp(zone)).ok()?;
    let name = usize::from(ZONES[group].1) * 4 + if long { 0 } else { 2 } + usize::from(daylight);
    let names: &'static str = ZONE_NAMES[names];
    names.split('|').nth(name).filter(|n| !n.is_empty())
}

fn index_of(name: &str) -> Option<u16> {
    NAMES
        .binary_search_by(|(n, _)| (*n).cmp(name))
        .ok()
        .map(|i| NAMES[i].1)
}

/// qt_splitLocaleName: the language, script and territory tags of a locale name. Tags end
/// at `_`, `-`, `.` or `@`; the language has two or three characters, a script is one of
/// QLocale's four-letter codes exactly as written, and any other second tag is the
/// territory. `None` for a name with no language.
fn split_name(name: &str) -> Option<(&str, &str, &str)> {
    let (mut lang, mut script, mut territory) = ("", "", "");
    let mut rest = name;
    let mut state = 0;
    while !rest.is_empty() && state < 3 {
        let end = rest.find(['_', '-', '.', '@']).unwrap_or(rest.len());
        let tag = &rest[..end];
        if tag.is_empty() || !tag.bytes().all(|c| c.is_ascii_alphanumeric()) {
            break;
        }
        let more = end < rest.len();
        rest = &rest[(end + usize::from(more)).min(rest.len())..];
        let after = if more { state + 1 } else { 3 };
        if state == 0 {
            if tag.len() != 2 && tag.len() != 3 {
                return None;
            }
            lang = tag;
            state = after;
        } else if state == 1 && tag.len() == 4 && SCRIPTS.binary_search(&tag).is_ok() {
            script = tag;
            state = after;
        } else {
            territory = tag;
            state = 3;
        }
    }
    (state != 0).then_some((lang, script, territory))
}

/// [`Locale::named`]'s locale, and whether the name had a script that the locale has too; None
/// for a name QLocale does not know.
fn find(name: &str) -> Option<(Locale, bool)> {
    let (lang, script, territory) = split_name(name)?;
    let lang = lang.to_ascii_lowercase();
    let lang = match LANGUAGES.binary_search_by(|(c, _)| (*c).cmp(lang.as_str())) {
        Ok(i) => LANGUAGES[i].1,
        Err(_) => lang.as_str(),
    };
    let territory = territory.to_ascii_uppercase();
    let both = (!script.is_empty() && !territory.is_empty())
        .then(|| format!("{lang}_{script}_{territory}"));
    let script = (!script.is_empty()).then(|| format!("{lang}_{script}"));
    let territory = (!territory.is_empty()).then(|| format!("{lang}_{territory}"));
    let names = [both, script, territory, Some(lang.to_string())];
    let found = |(at, n): (usize, &Option<String>)| Some((Locale(index_of(n.as_ref()?)?), at < 2));
    names.iter().enumerate().find_map(found)
}

/// The ZONE_NAMES row ICU has for the locale `id` (`sr_Latn_RS`, `de_DE`, `aa_BB_variant`).
///
/// ICU keeps a script that `id` names, and QLocale::name() has none: the row is then the one
/// tools/gen/locale/gen.py asked ICU for where that name is another locale's (sr_Latn_RS is
/// `sr_RS`, Serbian in Cyrillic), and the locale's own elsewhere. ICU has the root locale's
/// names for a script no locale of the language is written in (`ru_Latn_RU`: its parent is
/// the root, getParentLocaleID in uresbund.cpp) and for a language it has no data for. Its
/// data has `sh` as Serbian in Latin script.
fn icu_zone_names(id: &str) -> usize {
    let (lang, rest) = id.split_once(['_', '-']).unwrap_or((id, ""));
    let lang = lang.to_ascii_lowercase();
    let (second, third) = rest.split_once(['_', '-']).unwrap_or((rest, ""));
    let written = second.len() == 4 && second.bytes().all(|c| c.is_ascii_alphabetic());
    let script = match (written, lang.as_str()) {
        (true, _) => second[..1].to_ascii_uppercase() + &second[1..].to_ascii_lowercase(),
        (false, "sh") => "Latn".into(),
        (false, _) => String::new(),
    };
    if script.is_empty() {
        return find(id).map_or(ROOT_ZONE_NAMES, |(locale, _)| locale.icu_zone_names());
    }
    if lang == "sh" && script != "Latn" {
        return ROOT_ZONE_NAMES;
    }
    let lang = if lang == "sh" { "sr" } else { &lang };
    let rest = if written { third } else { rest };
    match find(&format!("{lang}_{script}_{rest}")) {
        Some((locale, true)) => {
            match SCRIPT_ZONE_NAMES.binary_search_by_key(&locale.0, |(record, _)| *record) {
                Ok(i) => SCRIPT_ZONE_NAMES[i].1 as usize,
                Err(_) => locale.icu_zone_names(),
            }
        }
        _ => ROOT_ZONE_NAMES,
    }
}

/// The environment QSystemLocale reads on Unix (qlocale_unix.cpp).
#[derive(Clone, PartialEq, Eq)]
struct SystemEnv {
    /// QSystemLocale::fallbackLocale: LC_ALL, LC_MESSAGES, LANG, and unless that is the C
    /// locale the first entry of LANGUAGE.
    base: String,
    numeric: String,
    time: String,
    monetary: String,
    messages: String,
    measurement: String,
    collate: String,
    /// What QSystemLocale's UILanguages lists: LANGUAGE's entries, or the messages locale.
    ui: String,
}

impl SystemEnv {
    fn read() -> SystemEnv {
        let var = |k: &str| std::env::var(k).ok().filter(|v| !v.is_empty());
        let all = var("LC_ALL");
        let lang = var("LANG").unwrap_or_else(|| "C".into());
        let category = |k: &str| {
            all.clone()
                .or_else(|| var(k))
                .unwrap_or_else(|| lang.clone())
        };
        let messages = category("LC_MESSAGES");
        let languages = var("LANGUAGE");
        let first = languages
            .as_deref()
            .and_then(|l| l.split(':').next())
            .filter(|l| !l.is_empty());
        let base = match first {
            Some(l) if messages != "C" && messages != "POSIX" => l.to_string(),
            _ => messages.clone(),
        };
        SystemEnv {
            base,
            numeric: category("LC_NUMERIC"),
            time: category("LC_TIME"),
            monetary: category("LC_MONETARY"),
            measurement: category("LC_MEASUREMENT"),
            collate: category("LC_COLLATE"),
            ui: languages.unwrap_or_else(|| messages.clone()),
            messages,
        }
    }

    /// QLocale::system()'s data: the fallback locale's, with what QSystemLocale::query
    /// answers from the category locales: digits, signs and group sizes from LC_NUMERIC, names and
    /// formats of dates and the first day of the week from LC_TIME, the currency's symbol
    /// and names from LC_MONETARY, the measurement system from LC_MEASUREMENT, list
    /// patterns from LC_MESSAGES.
    fn fields(&self) -> Vec<&'static str> {
        let mut v = Locale::named(&self.base).fields().to_vec();
        let numeric = Locale::named(&self.numeric).fields();
        // The decimal point, group separator, signs, zero digit and sizes of the groups.
        for i in [NUM, NUM + 1, NUM + 2, NUM + 3, NUM + 5, NUM + 6] {
            v[i] = numeric[i];
        }
        let time = Locale::named(&self.time).fields();
        v[..NUM].copy_from_slice(&time[..NUM]);
        v[FIRST_DAY] = time[FIRST_DAY];
        let monetary = Locale::named(&self.monetary).fields();
        for i in [NUM + 7, NUM + 8, CURRENCY_NAME] {
            v[i] = monetary[i];
        }
        let metric = ["metric", "other"].contains(&self.measurement.to_ascii_lowercase().as_str());
        v[MEASUREMENT] = if metric {
            "0"
        } else {
            Locale::named(&self.measurement).fields()[MEASUREMENT]
        };
        let messages = Locale::named(&self.messages).fields();
        v[LIST..LIST + 4].copy_from_slice(&messages[LIST..LIST + 4]);
        let mut ui: Vec<&str> = Vec::new();
        for entry in self.ui.split(':').filter(|e| split_name(e).is_some()) {
            for l in Locale::named(entry).ui_languages() {
                if !ui.contains(&l) {
                    ui.push(l);
                }
            }
        }
        if !ui.is_empty() {
            v[UI_LANGUAGES] = Box::leak(ui.join("|").into_boxed_str());
        }
        v
    }
}

impl Locale {
    /// QLocale::system(): see [`SystemEnv::fields`].
    pub const SYSTEM: Locale = Locale(u16::MAX);

    /// QLocale::c().
    pub fn c() -> Locale {
        Locale(0)
    }

    /// QLocale(name): "ru_RU.UTF-8", "ru-RU", "ru", "sr_Latn" ...; a name QLocale does not
    /// know gives the C locale. The language is matched without case by any of its ISO 639
    /// codes; of the script and the territory QLocale drops first the territory, then the
    /// script, until a locale it has data for is left (QLocaleData::findLocaleIndex).
    pub fn named(name: &str) -> Locale {
        find(name).map_or_else(Locale::c, |(locale, _)| locale)
    }

    /// QLocale::system() for dates and times: QSystemLocale's lc_time (LC_ALL, LC_TIME, LANG).
    pub fn system_time() -> Locale {
        Locale::named(&SystemEnv::read().time)
    }

    /// The locale QCollator sorts by for QLocale::system(): QSystemLocale's lc_collate
    /// (LC_ALL, LC_COLLATE, LANG).
    pub fn system_collation() -> Locale {
        Locale::named(&SystemEnv::read().collate)
    }

    pub(crate) fn fields(self) -> &'static [&'static str] {
        if self == Locale::SYSTEM {
            let env = SystemEnv::read();
            return SYSTEM.with(|s| {
                let mut s = s.borrow_mut();
                if let Some((_, f)) = s.iter().find(|(e, _)| *e == env) {
                    return *f;
                }
                let f: &'static [&'static str] = Box::leak(env.fields().into_boxed_slice());
                s.push((env, f));
                f
            });
        }
        let i = self.0 as usize;
        SPLIT.with(|s| {
            let mut s = s.borrow_mut();
            *s[i].get_or_insert_with(|| {
                let v: Vec<&'static str> = RECORDS[i].split('\u{1f}').collect();
                debug_assert_eq!(v.len(), RECORD_LEN);
                Box::leak(v.into_boxed_slice())
            })
        })
    }

    /// QLocale::name(): `en_US`; `C` for the C locale.
    pub fn name(self) -> &'static str {
        self.fields()[NAME]
    }

    /// "QLocale(English, Latin, United States)": what QDebug, and so `String(locale)`,
    /// prints.
    pub fn description(self) -> String {
        let f = self.fields();
        let names = format!("{}, {}, {}", f[NAME + 1], f[NAME + 2], f[NAME + 3]);
        if self == Locale::SYSTEM {
            format!("QLocale::system()/* {names} */")
        } else {
            format!("QLocale({names})")
        }
    }

    /// QLocale::nativeLanguageName().
    pub fn native_language_name(self) -> &'static str {
        self.fields()[NATIVE_LANGUAGE]
    }

    /// QLocale::nativeTerritoryName().
    pub fn native_territory_name(self) -> &'static str {
        self.fields()[NATIVE_LANGUAGE + 1]
    }

    /// QLocale::percent().
    pub fn percent(self) -> &'static str {
        self.fields()[PERCENT]
    }

    /// QLocale::textDirection(): 0 left to right, 1 right to left.
    pub fn text_direction(self) -> u8 {
        self.fields()[PERCENT + 1].parse().unwrap_or(0)
    }

    /// QLocale::measurementSystem(): 0 metric, 1 imperial US, 2 imperial UK.
    pub fn measurement_system(self) -> u8 {
        self.fields()[MEASUREMENT].parse().unwrap_or(0)
    }

    /// QLocale::firstDayOfWeek() as QML counts days: Sunday = 0.
    pub fn first_day_of_week(self) -> usize {
        self.fields()[FIRST_DAY].parse().unwrap_or(1)
    }

    /// QLocale::weekdays() as QML counts days: Sunday = 0.
    pub fn week_days(self) -> impl Iterator<Item = u8> {
        self.fields()[FIRST_DAY + 1]
            .split(',')
            .filter_map(|d| d.parse().ok())
    }

    /// QLocale::uiLanguages().
    pub fn ui_languages(self) -> impl Iterator<Item = &'static str> {
        self.fields()[UI_LANGUAGES].split('|')
    }

    /// QLocale::currencySymbol(CurrencyDisplayName).
    pub fn currency_name(self) -> &'static str {
        self.fields()[CURRENCY_NAME]
    }

    /// QLocale::createSeparatedList().
    pub fn separated_list(self, items: &[String]) -> String {
        let f = self.fields();
        let join = |pattern: &str, a: &str, b: &str| {
            // The items may hold `%1` and `%2` themselves.
            let (head, tail) = pattern.split_once("%1").unwrap_or((pattern, ""));
            match tail.split_once("%2") {
                Some((mid, tail)) => format!("{head}{a}{mid}{b}{tail}"),
                None => {
                    let (h, t) = head.split_once("%2").unwrap_or((head, ""));
                    format!("{h}{b}{t}{a}{tail}")
                }
            }
        };
        match items {
            [] => String::new(),
            [one] => one.clone(),
            [a, b] => join(f[LIST], a, b),
            [a, b, rest @ .., last] => {
                let mut r = join(f[LIST + 1], a, b);
                for x in rest {
                    r = join(f[LIST + 2], &r, x);
                }
                join(f[LIST + 3], &r, last)
            }
        }
    }

    /// QLocale::formattedDataSize() with the locale's number data `numeric`: `format` is
    /// QLocale::DataSizeFormats (bit 0: powers of 1000 rather than 1024; bit 1: SI
    /// quantifiers rather than IEC ones).
    pub fn formatted_data_size(
        self,
        numeric: &crate::locale_num::Numeric,
        bytes: i64,
        precision: i32,
        format: u8,
    ) -> String {
        let (base, power) = if bytes == 0 {
            (1000.0, 0)
        } else if format & 1 != 0 {
            (1000.0, ((bytes.unsigned_abs() as f64).log10() as u32) / 3)
        } else {
            (1024.0, bytes.unsigned_abs().ilog2() / 10)
        };
        let number = if power == 0 {
            numeric.integer_to_string(bytes)
        } else {
            let scaled = bytes as f64 / f64::powi(base, power as i32);
            numeric.to_string(scaled, b'f', precision.min(3 * power as i32))
        };
        let units = self.fields()[UNITS];
        let i = match (power, format & 2 != 0) {
            (0, _) => 0,
            (p, true) => p as usize,
            (p, false) => p as usize + 6,
        };
        let unit = units.split('\u{1e}').nth(i).unwrap_or("");
        format!("{number} {unit}")
    }

    /// QLocale::dayName / standaloneDayName; `day` 0 = Sunday .. 6 = Saturday.
    pub fn day_name(self, day: usize, fmt: Fmt, standalone: bool) -> &'static str {
        let mon0 = (day + 6) % 7;
        self.fields()[fmt as usize * 38 + if standalone { 7 } else { 0 } + mon0]
    }

    /// QLocale::monthName / standaloneMonthName; `month` 0 = January .. 11, and "" past it.
    pub fn month_name(self, month: usize, fmt: Fmt, standalone: bool) -> &'static str {
        if month > 11 {
            return "";
        }
        self.fields()[fmt as usize * 38 + if standalone { 26 } else { 14 } + month]
    }

    pub fn am_text(self) -> &'static str {
        self.fields()[AM]
    }

    pub fn pm_text(self) -> &'static str {
        self.fields()[AM + 1]
    }

    fn format(self, fmt: Fmt, k: usize) -> &'static str {
        let long = fmt == Fmt::Long;
        self.fields()[FORMATS + if long { 0 } else { 3 } + k]
    }

    pub fn date_format(self, fmt: Fmt) -> &'static str {
        self.format(fmt, 0)
    }

    pub fn time_format(self, fmt: Fmt) -> &'static str {
        self.format(fmt, 1)
    }

    pub fn date_time_format(self, fmt: Fmt) -> &'static str {
        self.format(fmt, 2)
    }

    /// The name of the zone with IANA id `zone` in this locale's row of ZONE_NAMES: ICU's in
    /// the locale QLocale::name() names where ICU's default locale is en_US_POSIX, the one
    /// it has with no locale named in the environment; None where ICU has no name.
    pub fn zone_name(self, zone: &str, daylight: bool, long: bool) -> Option<&'static str> {
        zone_name_in(self.zone_names(), zone, daylight, long)
    }

    /// QTimeZone::displayName(StandardTime | DaylightTime, LongName | ShortName, locale) of
    /// the zone with IANA id `zone`, in a process whose default locale to ICU `default`
    /// gives; None where Qt has no name. For a locale that is_anglic Qt has another short
    /// name, the zone's own abbreviation. Qt asks ICU by QLocale::name(). Where ICU has no
    /// data for that name (`C`, `iu_CA`) the name is in ICU's default locale, which may name
    /// a script (`sr_Latn_RS`), and in ICU's root locale (`GMT+05:30`) when the default one
    /// has no data either or begins with the language asked for, `c` for the C locale: ICU
    /// then takes it for the one it did not find and does not look it up (findFirstExisting,
    /// uresbund.cpp).
    pub fn icu_zone_name(
        self,
        default: fn() -> String,
        zone: &str,
        daylight: bool,
        long: bool,
    ) -> Option<&'static str> {
        let names = if self.fields()[NO_ICU_DATA] == "1" {
            let asked = self
                .name()
                .split('_')
                .next()
                .unwrap_or("")
                .to_ascii_lowercase();
            let default = default();
            if default.to_ascii_lowercase().starts_with(&asked) {
                ROOT_ZONE_NAMES
            } else {
                icu_zone_names(&default)
            }
        } else {
            self.zone_names()
        };
        zone_name_in(names, zone, daylight, long)
    }

    /// This locale's row of ZONE_NAMES.
    fn zone_names(self) -> usize {
        self.fields()[ZONE].parse().unwrap_or(ROOT_ZONE_NAMES)
    }

    /// This locale's row of ZONE_NAMES when ICU has data for its name, the root's without.
    fn icu_zone_names(self) -> usize {
        if self.fields()[NO_ICU_DATA] == "1" {
            ROOT_ZONE_NAMES
        } else {
            self.zone_names()
        }
    }

    /// Whether this is the C locale or English in Latin script: QTimeZonePrivate's
    /// isAnglicLocale, the locales a zone's own abbreviation is the short name in.
    pub fn is_anglic(self) -> bool {
        self.fields()[ZONE + 1] == "1"
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ru_names_match_qt() {
        let ru = Locale::named("ru_RU.UTF-8");
        assert_eq!(ru.day_name(6, Fmt::Long, false), "суббота");
        assert_eq!(ru.day_name(6, Fmt::Short, false), "сб");
        assert_eq!(ru.day_name(1, Fmt::Narrow, true), "П");
        assert_eq!(ru.month_name(9, Fmt::Long, false), "октября");
        assert_eq!(ru.month_name(9, Fmt::Long, true), "октябрь");
        assert_eq!(ru.month_name(9, Fmt::Short, false), "окт.");
        assert_eq!(ru.am_text(), "AM");
        assert_eq!(ru.date_format(Fmt::Short), "dd.MM.yyyy");
        assert_eq!(ru.date_time_format(Fmt::Short), "dd.MM.yyyy HH:mm");
        assert_eq!(Locale::named("ru"), ru);
        let c = Locale::named("");
        assert_eq!(c, Locale::c());
        assert_eq!(c.day_name(0, Fmt::Short, false), "Sun");
        assert_eq!(Locale::named("de-DE").day_name(6, Fmt::Short, false), "Sa.");
        assert_eq!(Locale::named("de_DE").day_name(6, Fmt::Short, true), "Sa");
        assert_eq!(Locale::named("xx_YY"), Locale::c());
    }
}
